window.futvizVista("tabla-esperada","<div class=\"rx-mount\" data-rx=\"tabla_esperada\" data-rx-id=\"tabla-esperada\" style=\"min-height:640px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"tabla-esperada\"]={\"id\":\"tabla-esperada\",\"titulo\":\"Tabla real vs. esperada\",\"bajada\":\"Puntos reales contra los que val\u00edan las ocasiones de cada equipo, por liga y temporada.\",\"pregunta\":\"\u00bfQui\u00e9n est\u00e1 en el lugar que merece?\",\"tabla\":\"tabla-esperada\",\"queMirar\":\"El punto relleno son los **puntos reales** y el anillo los **puntos esperados** (xPts), los que val\u00edan las ocasiones de ese equipo en cada partido. La l\u00ednea que los une va en azul si el equipo sum\u00f3 m\u00e1s de lo esperado y en rojo si sum\u00f3 menos.\\n\\nA la derecha, el lugar que ocupar\u00eda por xPts y cu\u00e1ntos lugares est\u00e1 por encima (+) o por debajo (\u2212) de ese lugar. Pasa el cursor o toca un equipo para leer sus n\u00fameros.\",\"fuente\":\"Understat\",\"ligas\":[\"Bundesliga\",\"Serie A\",\"Ligue 1\",\"La Liga\",\"Premier League\"],\"ligaInicial\":\"Premier League\",\"temporadaInicial\":\"2025-26\"};</script>");